  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]private static void Install(){if(!Application.isEditor&&Arg()!=null)new GameObject("S2_Performance_CLI_Probe").AddComponent<S2PerformanceProbe>();}
  private IEnumerator Start()
