   var path=Path.GetFullPath(Arg());folder=Path.GetDirectoryName(path);Directory.CreateDirectory(folder);Application.runInBackground=true;report=new Result{unity=Application.unityVersion,api=SystemInfo.graphicsDeviceType.ToString(),cpu=SystemInfo.processorType,gpu=SystemInfo.graphicsDeviceName,os=SystemInfo.operatingSystem,ramMb=SystemInfo.systemMemorySize,vramMb=SystemInfo.graphicsMemorySize};var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){bool more;object current=null;try{more=stack.Peek().MoveNext();if(more)current=stack.Peek().Current;}catch(Exception e){report.error=e.ToString();break;}if(!more){(stack.Pop() as IDisposable)?.Dispose();continue;}if(current is IEnumerator nested){stack.Push(nested);continue;}yield return current;}while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();report.phase=phase;report.passed&=string.IsNullOrEmpty(report.error);File.WriteAllText(path,JsonUtility.ToJson(report,true));Application.Quit(report.passed?0:1);
