  private static void Check(bool v,string why){if(!v)throw new InvalidOperationException(why);}
  private void Position(Vector3 p,float yaw){var c=station.GetComponent<CharacterController>();c.enabled=false;station.transform.position=p;station.Player.SetLookAngles(yaw,0);station.Player.ResetMotion();c.enabled=true;Physics.SyncTransforms();}
