   phase="startup";var end=Time.realtimeSinceStartup+20;while(!station||!station.Ready){station=FindAnyObjectByType<StationSession>();if(Time.realtimeSinceStartup>end)throw new TimeoutException("Performance startup");yield return null;}camera=station.Player.View.GetComponent<Camera>();var pipe=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;report.pipeline=pipe?pipe.name:"null";report.width=Screen.width;report.height=Screen.height;report.hdr=pipe&&pipe.supportsHDR&&camera.allowHDR;report.displayHdr=HDROutputSettings.main!=null&&HDROutputSettings.main.active;report.useLlm=GameRuntimeOptions.UseLLM;Check(report.unity=="6000.6.7f1"&&report.api=="Direct3D11"&&report.pipeline=="ES_S2_ForwardHDR"&&report.width==1920&&report.height==1080&&report.hdr&&!report.displayHdr&&!report.useLlm,"Performance render baseline");station.Echo.AutomaticWarningsEnabled=false;station.Echo.TrySubmit(ScriptCommands.Wait(),out _);station.GetComponent<PlayerInputReader>().SetPointerCaptured(false);
   phase="ordinary_frames";yield return Measure();phase="pvs";yield return Pvs(pipe);report.passed=report.validFrames>=1400&&report.invalidFrames==0&&report.duplicates==0&&report.profilerEnabled&&report.profilerRestored&&report.pvsRestored&&report.pvsDraws[0]>report.pvsDraws[1]&&report.pvsDifference<1e-6f&&report.pvsStableDifference<1e-6f;phase="complete";
  }
  private IEnumerator Measure()
  {
   var wasEnabled=Profiler.enabled;var wasBinary=Profiler.enableBinaryLog;var oldFile=Profiler.logFile;report.rawFile=Path.GetFullPath(Path.Combine(folder,"S2Profiler.raw"));Profiler.enabled=false;Profiler.logFile=report.rawFile;Profiler.enableBinaryLog=true;Profiler.enabled=true;report.profilerEnabled=Profiler.enabled;
   try{yield return null;yield return null;var handles=new List<ProfilerRecorderHandle>();ProfilerRecorderHandle.GetAvailable(handles);report.availableCounters=handles.Select(ProfilerRecorderHandle.GetDescription).Where(d=>d.Name.Contains("Thread")||d.Name.Contains("Memory")||d.Name.Contains("GC ")||d.Name.Contains("Draw Calls")).Select(d=>d.Category.Name+":"+d.Name).ToArray();using var gc=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"GC Allocated In Frame",1);using var memory=ProfilerRecorder.StartNew(ProfilerCategory.Memory,"Total Used Memory",1);using var draws=ProfilerRecorder.StartNew(ProfilerCategory.Render,"Draw Calls Count",1);report.counters="gc="+gc.Valid+" memory="+memory.Valid+" draws="+draws.Valid;Check(gc.Valid&&memory.Valid&&draws.Valid,"Required counters");var timings=new FrameTiming[1];report.samples=new Sample[1500];var seen=new HashSet<ulong>(2048);var warm=Time.realtimeSinceStartup+10;while(Time.realtimeSinceStartup<warm){FrameTimingManager.CaptureFrameTimings();yield return null;FrameTimingManager.GetLatestTimings(1,timings);report.warmupChecksum=gc.LastValue^memory.LastValue^draws.LastValue;}
    var positions=new[]{new Vector3(0,.05f,-25),new Vector3(2,.05f,-2.5f),new Vector3(0,-3.95f,26),new Vector3(0,-3.95f,44),new Vector3(0,-3.95f,64)};var yaws=new[]{0f,-40f,0f,0f,0f};for(var zone=0;zone<5;zone++){Position(positions[zone],yaws[zone]);var stable=Time.realtimeSinceStartup+1;while(Time.realtimeSinceStartup<stable){FrameTimingManager.CaptureFrameTimings();yield return null;FrameTimingManager.GetLatestTimings(1,timings);}for(var i=0;i<300;i++){FrameTimingManager.CaptureFrameTimings();yield return null;var count=FrameTimingManager.GetLatestTimings(1,timings);var t=timings[0];var valid=count>0&&t.frameStartTimestamp!=0&&t.cpuFrameTime>0&&t.gpuFrameTime>0;var duplicate=valid&&!seen.Add(t.frameStartTimestamp);if(!valid)report.invalidFrames++;if(duplicate)report.duplicates++;valid&=!duplicate;if(valid)report.validFrames++;report.samples[zone*300+i]=new Sample{zone=zone,frame=Time.frameCount,valid=valid,duplicate=duplicate,timestamp=count>0?t.frameStartTimestamp:0,deltaMs=Time.unscaledDeltaTime*1000,cpuMs=count>0?t.cpuFrameTime:-1,gpuMs=count>0?t.gpuFrameTime:-1,mainMs=count>0?t.cpuMainThreadFrameTime:-1,renderMs=count>0?t.cpuRenderThreadFrameTime:-1,presentWaitMs=count>0?t.cpuMainThreadPresentWaitTime:-1,gcBytes=gc.LastValue,usedBytes=memory.LastValue,drawCalls=draws.LastValue};}yield return Snap("Zone_"+zone);}
   }finally{Profiler.enabled=false;Profiler.enableBinaryLog=wasBinary;Profiler.logFile=oldFile;Profiler.enabled=wasEnabled;report.profilerRestored=Profiler.enabled==wasEnabled&&Profiler.enableBinaryLog==wasBinary&&Profiler.logFile==oldFile;}
  }
  private IEnumerator Pvs(UniversalRenderPipelineAsset pipe)
